            if (v2SteamProfile.LastLogoffOption.IsSet)
                writer.WriteString("last_logoff", v2SteamProfile.LastLogoffOption.Value!.Value.ToString(LastLogoffFormat));

            if (v2SteamProfile.CreatedAtOption.IsSet)
                writer.WriteString("created_at", v2SteamProfile.CreatedAtOption.Value!.Value.ToString(CreatedAtFormat));
        }
    }
}
